#include <cassert>
#include <vector>

int main() {
    std::vector<int> st;
    st.push_back(1);
    st.push_back(2);
    st.push_back(3);
    assert(st.back() == 3);
    st.pop_back();                                   // returns void
    assert(st.back() == 2 && st.size() == 2);

    std::vector<int> squares;
    for (int x = 0; x < 5; ++x)
        if (x % 2 == 0) squares.push_back(x * x);
    assert((squares == std::vector<int>{0, 4, 16}));

    std::vector<std::vector<int>> grid(2, std::vector<int>(3, 0));   // rows are copies
    grid[0][0] = 1;
    assert(grid[1][0] == 0);
    return 0;
}

#include <cassert>
#include <deque>
#include <queue>
#include <vector>

int main() {
    // BFS on edges 0-1, 0-2, 1-3
    std::vector<std::vector<int>> adj = {{1, 2}, {0, 3}, {0}, {1}};
    std::vector<int> dist(4, -1);
    std::queue<int> q;
    q.push(0);
    dist[0] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();                                     // std::queue::pop removes the FRONT
        for (int v : adj[u])
            if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }
    }
    assert((dist == std::vector<int>{0, 1, 1, 2}));

    std::deque<int> d = {2};
    d.push_front(1);
    d.push_back(3);
    assert(d.front() == 1 && d.back() == 3);
    return 0;
}

#include <cassert>
#include <functional>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> maxh;                   // max-heap by default
    for (int x : {3, 1, 4}) maxh.push(x);
    assert(maxh.top() == 4);

    std::priority_queue<int, std::vector<int>, std::greater<int>> minh;   // what heapq gives you
    for (int x : {3, 1, 4}) minh.push(x);
    assert(minh.top() == 1);
    minh.pop();
    assert(minh.top() == 3);
    return 0;
}

