#include <cassert>
#include <vector>

struct ListNode {
    int val;
    ListNode* next;
    explicit ListNode(int v, ListNode* n = nullptr) : val(v), next(n) {}
};

ListNode* reverse(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* curr = head;
    while (curr) {
        ListNode* nxt = curr->next;      // C++ needs the temporary
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }
    return prev;
}

int main() {
    ListNode c(3), b(2, &c), a(1, &b);
    std::vector<int> out;
    for (ListNode* p = reverse(&a); p; p = p->next) out.push_back(p->val);
    assert((out == std::vector<int>{3, 2, 1}));
    return 0;
}

