class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build(vals):
    dummy = ListNode()                   # dummy head: no special case for the first node
    tail = dummy
    for v in vals:
        tail.next = ListNode(v)
        tail = tail.next
    return dummy.next


def to_list(head):
    out = []
    while head:                          # None is falsy, like nullptr
        out.append(head.val)
        head = head.next
    return out


def reverse(head):
    prev, curr = None, head
    while curr:
        curr.next, prev, curr = prev, curr, curr.next   # right side evaluated first
    return prev


assert to_list(reverse(build([1, 2, 3]))) == [3, 2, 1]
assert reverse(None) is None


def height(node):
    if node is None:
        return 0
    return 1 + max(height(node.left), height(node.right))


assert height(TreeNode(1, TreeNode(2, TreeNode(4)), TreeNode(3))) == 3

