#include <algorithm>
#include <cassert>
#include <vector>

int main() {
    std::vector<int> a = {1, 2, 2, 2, 5};
    auto lo = std::lower_bound(a.begin(), a.end(), 2) - a.begin();
    auto hi = std::upper_bound(a.begin(), a.end(), 2) - a.begin();
    assert(lo == 1 && hi == 4 && hi - lo == 3);
    assert(std::lower_bound(a.begin(), a.end(), 9) == a.end());

    a.insert(std::upper_bound(a.begin(), a.end(), 3), 3);   // O(N) shift, same as insort
    assert((a == std::vector<int>{1, 2, 2, 2, 3, 5}));
    return 0;
}

