int main() {
    std::vector<std::pair<std::string, int>> v = {{"cat", 90}, {"amy", 95}, {"bob", 90}};
    std::stable_sort(v.begin(), v.end(),
                     [](const auto& a, const auto& b) { return a.second > b.second; });
    assert(v[0].first == "amy" && v[1].first == "cat" && v[2].first == "bob");

    std::vector<std::string> nums = {"3", "30", "34"};   // largest number
    std::sort(nums.begin(), nums.end(),
              [](const std::string& a, const std::string& b) { return a + b > b + a; });
    assert(nums[0] == "34" && nums[1] == "3" && nums[2] == "30");
    return 0;
}

#include <cassert>
#include <unordered_map>
#include <vector>

long long fib(int n, std::unordered_map<int, long long>& memo) {
    if (n < 2) return n;
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    long long r = fib(n - 1, memo) + fib(n - 2, memo);
    memo[n] = r;
    return r;
}

int main() {
    std::unordered_map<int, long long> memo;
    assert(fib(50, memo) == 12586269025LL);

    int n = 100000;                                  // path 0 -> 1 -> ... -> n-1
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i + 1 < n; ++i) adj[i].push_back(i + 1);
    std::vector<int> st = {0};
    std::vector<bool> seen(n, false);
    seen[0] = true;
    int visited = 0;
    while (!st.empty()) {                            // iterative DFS
        int u = st.back();
        st.pop_back();
        ++visited;
        for (int v : adj[u])
            if (!seen[v]) { seen[v] = true; st.push_back(v); }
    }
    assert(visited == n);
    return 0;
}

