import sys
from functools import cache, lru_cache


@cache                                   # same as lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)


assert fib(90) == 2880067194370816120   # without the cache this never finishes


@lru_cache(maxsize=None)
def paths(r, c):                         # grid DP, top-down
    if r == 0 or c == 0:
        return 1
    return paths(r - 1, c) + paths(r, c - 1)


assert paths(2, 2) == 6
paths.cache_clear()                      # reset between test cases

assert sys.getrecursionlimit() == 1000

n = 100_000
adj = [[i + 1] for i in range(n - 1)] + [[]]    # a path 0 -> 1 -> ... -> n-1


def dfs(u):
    for v in adj[u]:
        dfs(v)


try:
    dfs(0)
    deep_ok = True
except RecursionError:
    deep_ok = False
assert deep_ok is False


def dfs_iter(start):                     # explicit stack: no depth limit
    seen, stack = {start}, [start]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return len(seen)


assert dfs_iter(0) == n

